const manualForm=document.querySelector('#manual-contact-form'),operationForm=document.querySelector('#operation-form'),operationMessage=document.querySelector('#operation-feedback');let operationRows=[];
async function opApi(path,data){const response=await fetch('/api/admin/'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await response.json();if(!response.ok)throw Error(body.error||'Não foi possível concluir.');return body;}
function updateTeam(period){window.dispatchEvent(new CustomEvent('admin-data-updated',{detail:{periodo:period}}));}
manualForm.onsubmit=async e=>{e.preventDefault();if(!manualForm.reportValidity())return;const button=manualForm.querySelector('button[type=submit]');button.disabled=true;const data=Object.fromEntries(new FormData(manualForm));data.ciente=data.ciente==='on';try{await opApi('entries',data);document.querySelector('#manual-contact-feedback').textContent='Contato cadastrado. As métricas foram atualizadas.';manualForm.reset();updateTeam(new Date().toISOString().slice(0,7));await refreshContacts();}catch(error){document.querySelector('#manual-contact-feedback').textContent=error.message;}finally{button.disabled=false;}};
async function refreshContacts(){try{const q=document.querySelector('#operation-contact-search').value;const d=await opApi('entries?busca='+encodeURIComponent(q));const select=operationForm.elements.cadastro_id,previous=select.value;select.replaceChildren(new Option('Sem vínculo com um cadastro',''));for(const c of d.items)select.add(new Option(c.nome+' · '+c.contato,c.id));if(d.items.some(c=>c.id===previous))select.value=previous;}catch(e){operationMessage.textContent=e.message;}}
async function refreshOperations(){try{const d=await opApi('operacoes');operationRows=d.items;const select=document.querySelector('#operation-existing');select.replaceChildren(new Option('Novo registro',''));const list=document.querySelector('#operations-list');list.replaceChildren();for(const row of operationRows){select.add(new Option(row.data_ocorrencia+' · '+(row.descricao_tipo||(row.tipo==='cesta'?'Entrega de cestas':row.tipo==='atendimento'?'Atendimento':'Outra atividade'))+' · '+row.quantidade,row.id));const article=document.createElement('details');article.className='entry';const summary=document.createElement('summary');summary.textContent=row.data_ocorrencia+' · '+(row.descricao_tipo||(row.tipo==='cesta'?'Cestas entregues':row.tipo==='atendimento'?'Atendimentos realizados':'Outra atividade'))+' · '+row.quantidade;const text=document.createElement('p');text.textContent=(row.cadastro_nome?'Contato: '+row.cadastro_nome+'. ':'Sem vínculo nominal. ')+(row.notas||'');article.append(summary,text);list.append(article);}if(!operationRows.length)list.textContent='Nenhum atendimento ou entrega registrado individualmente.';}catch(e){operationMessage.textContent=e.message;}}
document.querySelector('#operation-existing').onchange=e=>{const row=operationRows.find(r=>r.id===e.target.value);operationForm.reset();document.querySelector('#operation-delete').disabled=!row;if(row&&row.cadastro_id&&![...operationForm.elements.cadastro_id.options].some(o=>o.value===row.cadastro_id))operationForm.elements.cadastro_id.add(new Option(row.cadastro_nome||'Contato vinculado',row.cadastro_id));if(row)for(const key of ['id','tipo','descricao_tipo','data_ocorrencia','quantidade','notas','cadastro_id'])operationForm.elements[key].value=row[key]||'';};document.querySelector('#operation-search').onclick=refreshContacts;
operationForm.onsubmit=async e=>{e.preventDefault();if(!operationForm.reportValidity())return;const button=operationForm.querySelector('button[type=submit]');button.disabled=true;if(!operationForm.elements.id.value)operationForm.elements.id.value=crypto.randomUUID();const data=Object.fromEntries(new FormData(operationForm));data.quantidade=Number(data.quantidade);try{const r=await opApi('operacoes',data);operationMessage.textContent='Registro salvo. Atendimentos e cestas foram recalculados para '+data.data_ocorrencia.slice(0,7)+'. Para outra ocorrência, escolha Novo registro.';updateTeam(data.data_ocorrencia.slice(0,7));await refreshOperations();document.querySelector('#operation-existing').value=r.id;document.querySelector('#operation-delete').disabled=false;}catch(error){operationMessage.textContent=error.message;}finally{button.disabled=false;}};operationForm.elements.data_ocorrencia.max=new Date().toISOString().slice(0,10);refreshContacts();refreshOperations();
document.querySelector('#admin-results-export').onclick=async()=>{try{const period=document.querySelector('#overview-period').value,d=await opApi('overview?periodo='+period),values={periodo:period,alcance_registrado:d.pessoas,cadastros:d.cadastros,atendimentos:d.atendimentos,cestas:d.cestas,familias:d.publicacao?.familias??'Não publicado',voluntarios:d.voluntarios,acoes:d.acoes.find(a=>a.publicada===1)?.total||0};const cell=v=>'"'+String(/^[=+\-@\t\r]/.test(String(v))?"'"+v:v).replaceAll('"','""')+'"';const csv='\uFEFF'+[Object.keys(values),Object.values(values)].map(r=>r.map(cell).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='resultados-'+period+'.csv';a.click();URL.revokeObjectURL(url);}catch(e){operationMessage.textContent=e.message;}};

document.querySelector('#operation-delete').onclick=async e=>{const id=operationForm.elements.id.value;if(!id)return;if(!confirm('Excluir definitivamente este registro e retirar sua quantidade dos indicadores? Esta ação não pode ser desfeita.'))return;e.target.disabled=true;try{const r=await opApi('operacoes/excluir',{id,confirmacao:id});operationForm.reset();await refreshOperations();updateTeam(r.periodo);operationMessage.textContent='Registro excluído. Os indicadores foram recalculados.';}catch(error){operationMessage.textContent=error.message;e.target.disabled=false;}};
